using System.Numerics;
using System.Text.Json;
using FighterPort.Core;

internal static class LibraryChecks
{
    public static async Task RunAsync(FighterProject original,Scene alternate,string directory,Action<bool,string> check)
    {
        string folder=Path.Combine(directory,"library-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string root=Path.Combine(folder,"cache");var store=new AnimationLibraryStore(root);
        string sourceFile=Path.Combine(folder,"authored.fighterport");await ProjectStore.SaveAsync(original,sourceFile);string originalHash=ProjectStore.Hash(sourceFile);
        var description=new LibrarySourceDescription("fighterport.project.v1",new("Original fixture","FighterPort","fixture-1"),"Mannequin","Original","Original authored geometry and animation fixture",true){BuildVerified=true};
        var entry=await store.RegisterAsync(original,description,[new("project",sourceFile)]);var duplicate=await store.RegisterAsync(original,description,[new("project",sourceFile)]);
        check(entry.Id==duplicate.Id&&(await store.LoadAsync()).Sources.Length==1,"Library deduplicates the same reviewed source instead of duplicating its clips");
        var reopenedStore=new AnimationLibraryStore(root);var clip=await reopenedStore.OpenClipAsync(entry.Id,original.Clips[0].Id);
        check(clip.Scene.SkeletonRevision==original.Scene.SkeletonRevision&&clip.Clips.Single().Revision==original.Clips[0].Revision&&clip.LibraryRegistrationId==entry.Id,"Global library restart retains exact original model/skeleton and clip revisions");
        check(clip.SourceBuild==description.Build&&clip.SourceBuildVerified&&clip.SourceProvider==description.Provider,"Library retains declared game/build, verification status and provider separately");
        var complete=await reopenedStore.OpenClipAsync(entry.Id,original.Clips[0].Id,includeSourceClips:true);check(complete.Clips.Length==original.Clips.Length&&complete.Clips.All(c=>original.Clips.Any(o=>o.Id==c.Id&&o.Revision==c.Revision)),"Prepared browser cache retains all authentic source clip revisions for selection without repeated decoding");
        await reopenedStore.VerifySourceAsync(entry);check(reopenedStore.IsCurrent(entry),"Apply verifies streamed raw/prepared proofs without decoding the authentic source project again");
        string cataloguePath=Path.Combine(root,"catalogue.json");var catalogue=await store.LoadAsync();await File.WriteAllTextAsync(cataloguePath,JsonSerializer.Serialize(catalogue with{Sources=[entry with{Clips=entry.Clips.Select((c,i)=>i==0?c with{Revision=Guid.NewGuid()}:c).ToArray()}]},ProjectStore.Json));
        bool changedManifest=false;try{await store.VerifySourceAsync(entry);}catch(InvalidDataException){changedManifest=true;}check(changedManifest&&!store.IsCurrent(entry),"A changed stable clip revision invalidates Apply even when package, model and source identity labels are unchanged");await File.WriteAllTextAsync(cataloguePath,JsonSerializer.Serialize(catalogue,ProjectStore.Json));
        string preparedPath=Path.Combine(root,"prepared",entry.PackageHash+".fighterport");var preparedBytes=await File.ReadAllBytesAsync(preparedPath);await File.WriteAllBytesAsync(preparedPath,preparedBytes.Append((byte)32).ToArray());bool changedPrepared=false;try{await store.VerifySourceAsync(entry);}catch(InvalidDataException){changedPrepared=true;}check(changedPrepared,"Streamed Apply proof verification rejects changed prepared bytes independently of trusted catalogue metadata");await File.WriteAllBytesAsync(preparedPath,preparedBytes);
        var target=new EditorDocument(original with{Name="Target fighter"});target.SelectedBone=4;target.KeyTransform(0,Transform.Identity with{Translation=new(.125f,0,0)});target.Seek(3.25);target.Clock.Speed=.5;target.Clock.LoopOverride=false;target.SetPose(1,original.Scene.Bones[1].Rest with{Translation=new(0,1.1f,0)});
        var targetBefore=target.Project;string pose=JsonSerializer.Serialize(target.Evaluate().Local,ProjectStore.Json);target.BeginSourcePreview(clip,clip.Clips[0].Id);
        check(target.IsSourcePreview&&ReferenceEquals(target.AuthoringProject,targetBefore)&&!target.CanUndo,"Original preview uses the same document while retaining the fighter and its undo history");
        bool blocked=false;try{target.KeyTransform(0,Transform.Identity);}catch(InvalidOperationException){blocked=true;}
        check(blocked,"Original source preview rejects pose/key mutations");target.Undo();target.Redo();
        target.TogglePlayback();target.Tick(.25);check(target.Clock.Frame>0&&target.Evaluate().World[8]!=AnimationService.Evaluate(clip.Scene,clip.Clips[0],0).World[8],"Source preview plays actual source-rig poses through the shared clock/evaluator");
        string savedTarget=Path.Combine(folder,"saved-during-preview.fighterport");await ProjectStore.SaveAsync(target.AuthoringProject,savedTarget);check((await ProjectStore.LoadAsync(savedTarget)).Name=="Target fighter","Saving during source preview serializes the target fighter, not the preview source");
        target.EndSourcePreview();check(ReferenceEquals(target.Project,targetBefore)&&target.SelectedBone==4&&target.Clock.Frame==3.25&&target.Clock.Speed==.5&&target.Clock.LoopOverride==false&&pose==JsonSerializer.Serialize(target.Evaluate().Local,ProjectStore.Json),"Returning restores target selection, fractional frame, overrides and transport settings exactly");
        target.Undo();check(target.Project.Clips[0].Revision==original.Clips[0].Revision,"Target Undo survives preview/playback/return and reverses the pre-preview key edit");target.Redo();
        var destination=original with{Id=Guid.NewGuid(),Scene=alternate,Clips=[]};var baked=RetargetService.Bake(clip,clip.Clips[0],AnimationControls.SetUp(clip.Scene),destination,AnimationControls.SetUp(alternate));check(baked.Value is not null,"A library clip retargets onto renamed bones with different bind axes and proportions");
        var used=RetargetService.Apply(destination,baked.Value!);string usedPath=Path.Combine(folder,"library-target.fighterport");await ProjectStore.SaveAsync(used,usedPath);var usedAgain=await ProjectStore.LoadAsync(usedPath);
        check(usedAgain.LibrarySources.Single().LibraryRegistrationId==entry.Id&&usedAgain.LibrarySources[0].Build==description.Build&&usedAgain.Clips[0].Id!=clip.Clips[0].Id,"Target save/reopen retains source library/build provenance and independent target keys");
        check(AnimationControls.DeformChecksum(usedAgain.Scene)==AnimationControls.DeformChecksum(alternate)&&ProjectStore.Hash(sourceFile)==originalHash,"Library reuse never changes source bytes or the target's deform rig/weights");
        string rawModel=Path.Combine(folder,"original.model"),rawMotion=Path.Combine(folder,"original.motion");await File.WriteAllBytesAsync(rawModel,[1,2,3,4]);await File.WriteAllBytesAsync(rawMotion,[5,6,7,8]);
        var modelRef=new NativeResourceRef(rawModel,"root/model",ProjectStore.Hash(rawModel),"ORIGINAL_MODEL",7);var motionRef=new NativeResourceRef(rawMotion,"root/motion/3",ProjectStore.Hash(rawMotion),"ORIGINAL_MOTION",4);var modelId=Guid.NewGuid();
        var nativeClip=original.Clips[0] with{Rate=new(30),Tracks=original.Clips[0].Tracks.Append(new BoneTrack("OriginalDormantSelector",new Curve?[9])).ToArray(),Source=new(Guid.NewGuid(),motionRef,modelRef,original.Scene.SkeletonRevision,new(30),modelId,"Original fixture association")};
        var foreign=nativeClip with{Id=Guid.NewGuid(),Revision=Guid.NewGuid(),Name="Original foreign active joint",Tracks=nativeClip.Tracks.Append(new BoneTrack("ForeignActiveJoint",[null,null,null,new([new(0,45)]),null,null,null,null,null])).ToArray()};
        var native=original with{Clips=[nativeClip,foreign],SourceModels=[new(modelId,"Original fixture",modelRef,original.Scene.Bones,"Original fixture axes")]};var nativeDescription=description with{Provider="native.original-fixture.v1",Character="Native fixture"};
        var nativeEntry=await store.RegisterAsync(native,nativeDescription,[new("model",rawModel),new("motion",rawMotion)]);
        check(nativeEntry.Clips.Length==1&&nativeEntry.Unresolved.Single().MissingBones.SequenceEqual(new[]{"ForeignActiveJoint"}),"Empty absent-bone native entries do not exclude usable clips; real foreign animation channels remain excluded");
        var dormantBake=RetargetService.Bake(native,nativeClip,AnimationControls.SetUp(native.Scene),destination,AnimationControls.SetUp(destination.Scene));check(dormantBake.Value is not null&&dormantBake.Value.Source.Clip.Tracks.Any(t=>t.Bone=="OriginalDormantSelector"&&!t.HasKeys)&&!dormantBake.Value.Source.Scene.Bones.Any(b=>b.Name=="OriginalDormantSelector"),"Retargeting preserves dormant native entry identity without inventing a source bone or dropping real animated channels");
        check(RetargetService.Bake(native,foreign,AnimationControls.SetUp(native.Scene),destination,AnimationControls.SetUp(destination.Scene)).Value is null,"An active channel absent from the authentic source rig still blocks direct retargeting precisely");
        File.Delete(rawModel);File.Delete(rawMotion);File.Delete(sourceFile);
        var offline=await reopenedStore.OpenClipAsync(nativeEntry.Id,nativeClip.Id);var offlineAuthored=await reopenedStore.OpenClipAsync(entry.Id,original.Clips[0].Id);
        check(ProjectStore.ValidateSources(offline).Length==0&&offline.Clips[0].Source!.Resource.OriginalPath==rawMotion&&offline.Clips[0].Source!.Model!.OriginalPath==rawModel,"Verified cached originals allow offline reuse while retaining original native paths and hashes");
        check(offline.Clips[0].Rate==new RationalRate(30)&&offline.Clips[0].Source!.Resource.Format=="ORIGINAL_MOTION"&&offlineAuthored.Clips.Length==1,"Library preserves native format/timebase independently of Brawl CHR0 and source location");
        bool unrelated=false;try{await store.OpenClipAsync(nativeEntry.Id,original.Clips[1].Id);}catch(InvalidDataException){unrelated=true;}check(unrelated,"Library rejects a clip belonging to another source instead of guessing ownership by name");
        string cacheMotion=offline.Clips[0].Source!.Resource.Path;await File.WriteAllBytesAsync(cacheMotion,[99]);bool corrupt=false;try{await store.OpenClipAsync(nativeEntry.Id,nativeClip.Id);}catch(InvalidDataException){corrupt=true;}check(corrupt,"Corrupt cached native originals block preview/retarget with a hash error");
        bool corruptApply=false;try{await store.VerifySourceAsync(nativeEntry);}catch(InvalidDataException){corruptApply=true;}check(corruptApply,"Apply independently rechecks cached raw bytes even when an authentic source is already prepared in memory");
        bool missing=false;File.Delete(cacheMotion);try{await store.OpenClipAsync(nativeEntry.Id,nativeClip.Id);}catch(InvalidDataException){missing=true;}check(missing,"Missing cached originals produce a precise failure without deleting the catalogue");
        using var cancelled=new CancellationTokenSource();cancelled.Cancel();bool stopped=false;try{await store.RegisterAsync(original,description,[new("project",sourceFile)],cancelled.Token);}catch(OperationCanceledException){stopped=true;}check(stopped&&(await store.LoadAsync()).Sources.Length==2,"Cancelled registration leaves all committed library entries intact");
        bool cancelledProof=false;try{await store.VerifySourceAsync(entry,cancelled.Token);}catch(OperationCanceledException){cancelledProof=true;}check(cancelledProof,"Cancelled Apply proof verification stops before publishing or committing target data");
        bool unreviewed=false;try{await store.RegisterAsync(original,description with{Reviewed=false},[new("project",sourceFile)]);}catch(InvalidDataException){unreviewed=true;}check(unreviewed,"Unreviewed source model associations cannot enter the usable library");
    }
}
